insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-earn-from-holiday-home-rentals', 'Can I earn from holiday home rentals?', '<p>Yes — short-term <a href="/collection/rentals">holiday and long-term rentals</a> in licensed holiday homes can generate seasonal income. Check DTCM licensing for your building.</p>', 'Can I earn from holiday home rentals?', 142, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-the-difference-between-gross-and-net-yield', 'What is the difference between gross and net yield?', '<p>Gross = annual rent / price; net deducts service charges, maintenance, and vacancy. Agent provides estimates on <a href="/pages/contact">contact our team</a>.</p>', 'What is the difference between gross and net yield?', 143, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'should-i-buy-off-plan-for-investment', 'Should I buy off-plan for investment?', '<p>Off-plan offers payment plans and potential capital gain but carries completion risk. Due diligence in <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Should I buy off-plan for investment?', 144, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'which-dubai-areas-have-highest-rental-demand', 'Which Dubai areas have highest rental demand?', '<p>Marina, JVC, Business Bay, and Downtown remain strong for tenants. Browse <a href="/search">property search</a> by community.</p>', 'Which Dubai areas have highest rental demand?', 145, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-non-residents-collect-rent-remotely', 'Can non-residents collect rent remotely?', '<p>Yes with property management and proper accounting. <a href="/pages/contact">contact our team</a> for management referrals.</p>', 'Can non-residents collect rent remotely?', 146, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-are-service-charges-impact-on-roi', 'What are service charges impact on ROI?', '<p>SC reduces net yield — typically AED 12–25/sq ft annually. Request SC on any <a href="/collection/sales">properties for sale</a> listing.</p>', 'What are service charges impact on ROI?', 147, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-flipping-property-allowed-in-dubai', 'Is flipping property allowed in Dubai?', '<p>Resale before handover may need developer NOC and fees. Hold period affects ROI — see <a href="/pages/buying-guide">Buying Guide</a>.</p>', 'Is flipping property allowed in Dubai?', 148, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'where-do-i-browse-investment-ready-listings', 'Where do I browse investment-ready listings?', '<p><a href="/collection/sales">properties for sale</a>, <a href="/collection/new">new listings</a>, and <a href="/collection/all">all listings</a>. <a href="/pages/about">About GW Vacation Homes</a> describes our advisory approach for investors.</p>', 'Where do I browse investment-ready listings?', 149, true from public.faq_categories where slug = 'investment-roi' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
